14	diff --git a/ForecastAccuracy.php b/ForecastAccuracy.php
15	new file mode 100644
16	index 0000000..4cd247d
17	--- /dev/null
18	+++ b/ForecastAccuracy.php
19	@@ -0,0 +1,151 @@
20	+<?php
21	+
22	+// Accuracy of past forecasts: forecast quantities (revised where entered) against the sales that followed.
23	+// MAD, POA, MSE and RMSE per item, per category or per method for a chosen range of months.
24	+
25	+require(__DIR__ . '/includes/session.php');
26	+
27	+$Title = __('Forecast Accuracy');
28	+$ViewTopic = 'Forecasting';
29	+$BookMark = 'ForecastAccuracy';
30	+include('includes/header.php');
31	+include('includes/ForecastFormFunctions.php');
32	+
33	+ForecastPageTitle($Title);
34	+ForecastNavigation();
35	+
36	+$Methods = ForecastMethods();
37	+$Held = ForecastHistoryRange();
38	+$Search = array(
39	+	'FromMonth' => $Held['from'] !== null ? substr($Held['from'], 0, 7) : '',
40	+	'ToMonth' => $Held['to'] !== null ? substr($Held['to'], 0, 7) : '',
41	+	'ViewBy' => 'item',
42	+	'CategoryID' => '',
43	+	'LowPOA' => '70',
44	+	'ActiveOnly' => ''
45	+);
46	+if (isset($_POST['Show'])) {
47	+	foreach ($Search as $Key => $Value) {
48	+		$Search[$Key] = isset($_POST[$Key]) ? $_POST[$Key] : '';
49	+	}
50	+}
51	+if (!in_array($Search['ViewBy'], array('item', 'category', 'method'))) {
52	+	$Search['ViewBy'] = 'item';
53	+}
54	+
55	+echo '<form method="post" action="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'), '">
56	+	<input type="hidden" name="FormID" value="', $_SESSION['FormID'], '" />
57	+	<fieldset>
58	+		<legend>', __('Accuracy report'), '</legend>
59	+		<field>
60	+			<label for="FromMonth">', __('From month'), ':</label>
61	+			<input type="month" name="FromMonth" id="FromMonth" required="required" value="', $Search['FromMonth'], '" />
62	+		</field>
63	+		<field>
64	+			<label for="ToMonth">', __('To month'), ':</label>
65	+			<input type="month" name="ToMonth" id="ToMonth" required="required" value="', $Search['ToMonth'], '" />
66	+		</field>
67	+		<field>
68	+			<label for="ViewBy">', __('Show accuracy per'), ':</label>
69	+			<select name="ViewBy" id="ViewBy">
70	+				<option value="item"', ($Search['ViewBy'] == 'item' ? ' selected="selected"' : ''), '>', __('Item and location'), '</option>
71	+				<option value="category"', ($Search['ViewBy'] == 'category' ? ' selected="selected"' : ''), '>', __('Stock category'), '</option>
72	+				<option value="method"', ($Search['ViewBy'] == 'method' ? ' selected="selected"' : ''), '>', __('Forecasting method'), '</option>
73	+			</select>
74	+		</field>
75	+		<field>
76	+			<label for="CategoryID">', __('Stock category'), ':</label>';
77	+ForecastCategorySelect('CategoryID', $Search['CategoryID'], __('All categories'));
78	+echo '</field>
79	+		<field>
80	+			<label for="LowPOA">', __('Flag accuracy below (POA %)'), ':</label>
81	+			<input type="text" class="number" name="LowPOA" id="LowPOA" size="4" value="', $Search['LowPOA'], '" />
82	+		</field>
83	+		<field>
84	+			<label for="ActiveOnly">', __('Active forecasts only'), ':</label>
85	+			<input type="checkbox" name="ActiveOnly" id="ActiveOnly" value="1"', ($Search['ActiveOnly'] == '1' ? ' checked="checked"' : ''), ' />
86	+		</field>
87	+		<fieldhelp>', __('Every forecast generated counts, including those later superseded, unless only active forecasts are chosen. POA = 100 - 100 x sum of absolute errors / sum of actual sales.'), '</fieldhelp>
88	+	</fieldset>
89	+	<div class="centre"><input type="submit" name="Show" value="', __('Show Accuracy'), '" /></div>
90	+</form>';
91	+
92	+if (isset($_POST['Show'])) {
93	+	if (!preg_match('/^\d{4}-\d{2}$/', $Search['FromMonth']) or !preg_match('/^\d{4}-\d{2}$/', $Search['ToMonth']) or $Search['FromMonth'] > $Search['ToMonth']) {
94	+		prnMsg(__('Enter a valid range of months'), 'error');
95	+	} else {
96	+		$Low = is_numeric($Search['LowPOA']) ? (float) $Search['LowPOA'] : 70;
97	+		$Where = ForecastLocationAccessSQL();
98	+		if ($Search['CategoryID'] != '') {
99	+			$Where .= " AND stockmaster.categoryid = '" . $Search['CategoryID'] . "'";
100	+		}
101	+		if ($Search['ActiveOnly'] == '1') {
102	+			$Where .= " AND forecasts.activeflag = 1";
103	+		}
104	+		$Rows = ForecastActualsVsForecast($Search['FromMonth'] . '-01', $Search['ToMonth'] . '-01', $Where);
105	+		if (count($Rows) == 0) {
106	+			prnMsg(__('No forecast months in this range have sales history to compare with. Extract the sales history up to the latest month first.'), 'info');
107	+		} else {
108	+			$Groups = array();
109	+			$AllActual = $AllForecast = array();
110	+			foreach ($Rows as $Row) {
111	+				if ($Search['ViewBy'] == 'item') {
112	+					$Key = $Row['stockid'] . "\t" . $Row['loccode'];
113	+				} elseif ($Search['ViewBy'] == 'category') {
114	+					$Key = $Row['categoryid'];
115	+				} else {
116	+					$Key = sprintf('%02d', $Row['method']);
117	+				}
118	+				$Groups[$Key]['actual'][] = $Row['actualqty'];
119	+				$Groups[$Key]['forecast'][] = $Row['forecastqty'];
120	+				$AllActual[] = $Row['actualqty'];
121	+				$AllForecast[] = $Row['forecastqty'];
122	+			}
123	+			ksort($Groups);
124	+			$Names = array();
125	+			if ($Search['ViewBy'] == 'category') {
126	+				$Result = DB_query("SELECT categoryid, categorydescription FROM stockcategory");
127	+				while ($MyRow = DB_fetch_array($Result)) {
128	+					$Names[$MyRow['categoryid']] = $MyRow['categorydescription'];
129	+				}
130	+			}
131	+			echo '<br /><table class="selection">
132	+					<tr><th>', ($Search['ViewBy'] == 'item' ? __('Item and location') : ($Search['ViewBy'] == 'category' ? __('Stock category') : __('Method'))), '</th>
133	+						<th>', __('Months compared'), '</th><th>', __('Actual'), '</th><th>', __('Forecast'), '</th>
134	+						<th>', __('MAD'), '</th><th>', __('POA %'), '</th><th>', __('MSE'), '</th><th>', __('RMSE'), '</th><th></th></tr>';
135	+			$Flagged = 0;
136	+			foreach (($Groups + array('' => array('actual' => $AllActual, 'forecast' => $AllForecast, 'total' => true))) as $Key => $Group) {
137	+				$Measures = ForecastMeasures($Group['actual'], $Group['forecast']);
138	+				if (isset($Group['total'])) {
139	+					$Label = '<b>' . __('All forecasts selected') . '</b>';
140	+				} elseif ($Search['ViewBy'] == 'item') {
141	+					list($StockID, $LocCode) = explode("\t", $Key);
142	+					$Label = $StockID . ' - ' . ForecastLocationName($LocCode);
143	+				} elseif ($Search['ViewBy'] == 'category') {
144	+					$Label = $Key . (isset($Names[$Key]) ? ' - ' . $Names[$Key] : '');
145	+				} else {
146	+					$Label = (int) $Key . ' - ' . $Methods[(int) $Key]['name'];
147	+				}
148	+				$IsLow = (!isset($Group['total']) and $Measures['poa'] !== null and $Measures['poa'] < $Low);
149	+				if ($IsLow) {
150	+					$Flagged++;
151	+				}
152	+				echo '<tr class="striped_row">
153	+						<td>', $Label, '</td>
154	+						<td class="number">', $Measures['n'], '</td>
155	+						<td class="number">', ForecastNumber($Measures['sumactual'], 1), '</td>
156	+						<td class="number">', ForecastNumber($Measures['sumforecast'], 1), '</td>
157	+						<td class="number">', ForecastNumber($Measures['mad'], 2), '</td>
158	+						<td class="number"', ($IsLow ? ' style="background-color: #ffd2d2; font-weight: bold;"' : ''), '>', ($Measures['poa'] === null ? '-' : ForecastNumber($Measures['poa'], 1)), '</td>
159	+						<td class="number">', ForecastNumber($Measures['mse'], 2), '</td>
160	+						<td class="number">', ForecastNumber($Measures['rmse'], 2), '</td>
161	+						<td>', ($IsLow ? __('Low accuracy') : ''), '</td>
162	+					</tr>';
163	+			}
164	+			echo '</table>';
165	+			prnMsg(sprintf(__('%d of %d lines are below the accuracy threshold'), $Flagged, count($Groups)), $Flagged > 0 ? 'warn' : 'info');
166	+		}
167	+	}
168	+}
169	+
170	+include('includes/footer.php');
171	diff --git a/ForecastCompare.php b/ForecastCompare.php
172	new file mode 100644
173	index 0000000..282e3c5
174	--- /dev/null
175	+++ b/ForecastCompare.php
176	@@ -0,0 +1,119 @@
177	+<?php
178	+
179	+// Method comparison: one item's history is forecast with several methods, holding out its latest months,
180	+// and the forecasts are shown side by side with the actual sales and each method's accuracy.
181	+
182	+require(__DIR__ . '/includes/session.php');
183	+
184	+$Title = __('Forecast Method Comparison');
185	+$ViewTopic = 'Forecasting';
186	+$BookMark = 'ForecastCompare';
187	+include('includes/header.php');
188	+include('includes/ForecastFormFunctions.php');
189	+
190	+ForecastPageTitle($Title);
191	+ForecastNavigation();
192	+
193	+$Methods = ForecastMethods();
194	+$Post = array_merge(ForecastGetParameters(), ForecastRunDefaults(), $_POST);
195	+$Post['StockID'] = isset($_POST['StockID']) ? $_POST['StockID'] : (isset($_GET['StockID']) ? $_GET['StockID'] : '');
196	+$Post['Location'] = isset($_POST['Location']) ? $_POST['Location'] : '';
197	+
198	+echo '<form method="post" action="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'), '">
199	+	<input type="hidden" name="FormID" value="', $_SESSION['FormID'], '" />
200	+	<fieldset>
201	+		<legend>', __('Item to test'), '</legend>
202	+		<field>
203	+			<label for="StockID">', __('Item code'), ':</label>
204	+			<input type="text" name="StockID" id="StockID" size="21" maxlength="64" required="required" value="', $Post['StockID'], '" />
205	+		</field>
206	+		<field>
207	+			<label for="Location">', __('Location'), ':</label>';
208	+ForecastLocationSelect('Location', $Post['Location'], __('All locations combined'));
209	+echo '</field>
210	+	</fieldset>
211	+	<fieldset>
212	+		<legend>', __('Method parameters'), '</legend>';
213	+ForecastParameterFields($Post);
214	+echo '</fieldset>
215	+	<div class="centre"><input type="submit" name="Compare" value="', __('Compare Methods'), '" /></div>
216	+</form>';
217	+
218	+if (isset($_POST['Compare'])) {
219	+	$StockID = trim(mb_strtoupper($_POST['StockID']));
220	+	$LocCode = $_POST['Location'];
221	+	$P = ForecastParametersFromPost($_POST);
222	+	$HoldOut = (int) $P['holdout'];
223	+	$Description = ForecastItemDescription($StockID);
224	+	$Held = ForecastHistoryRange();
225	+	$Allowed = true;
226	+	if ($LocCode != '') {
227	+		$Result = DB_query("SELECT loccode FROM locationusers WHERE loccode = '" . $LocCode . "'
228	+							AND userid = '" . $_SESSION['UserID'] . "' AND canview = 1");
229	+		$Allowed = DB_num_rows($Result) > 0;
230	+	}
231	+	if ($Description === null) {
232	+		prnMsg(__('The item code entered is not a valid stock item'), 'error');
233	+	} elseif (!$Allowed) {
234	+		prnMsg(__('The location is not valid or you may not use it'), 'error');
235	+	} elseif ($HoldOut < 1 or $HoldOut > 12) {
236	+		prnMsg(__('The months held out must be a whole number from 1 to 12'), 'error');
237	+	} elseif ($Held['to'] === null) {
238	+		prnMsg(__('No sales history has been extracted yet'), 'error');
239	+	} else {
240	+		$Series = ForecastBuildSeries(ForecastItemRows($StockID, $LocCode), $Held['to']);
241	+		$X = $Series['values'];
242	+		if (count($X) <= $HoldOut) {
243	+			prnMsg(__('The item has too little sales history to hold out that many months'), 'error');
244	+		} else {
245	+			$Results = ForecastEvaluateMethods($X, $HoldOut, $P);
246	+			$TestStart = ForecastAddMonths($Held['to'], -($HoldOut - 1));
247	+			echo '<br /><p class="page_title_text">', $StockID, ' - ', $Description, ' (', ForecastLocationName($LocCode), '): ',
248	+				count($X), ' ', __('months of history,'), ' ', $HoldOut, ' ', __('held out'), '</p>';
249	+			if (count($Results) == 0) {
250	+				prnMsg(__('No method has enough history left to be tested'), 'warn');
251	+			} else {
252	+				echo '<table class="selection"><tr><th>', __('Method'), '</th>';
253	+				for ($i = 0; $i < $HoldOut; $i++) {
254	+					echo '<th>', ForecastMonthLabel(ForecastAddMonths($TestStart, $i)), '</th>';
255	+				}
256	+				echo '<th>', __('MAD'), '</th><th>', __('POA %'), '</th><th>', __('MSE'), '</th><th>', __('RMSE'), '</th></tr>
257	+					<tr><td><b>', __('Actual sales'), '</b></td>';
258	+				foreach (array_slice($X, count($X) - $HoldOut) as $Actual) {
259	+					echo '<td class="number"><b>', ForecastNumber($Actual, 1), '</b></td>';
260	+				}
261	+				echo '<td colspan="4"></td></tr>';
262	+				foreach ($Results as $Rank => $Result) {
263	+					echo '<tr class="striped_row"><td>', ($Rank == 0 ? '<b>' : ''), $Result['method'], ' - ', $Methods[$Result['method']]['name'],
264	+						($Rank == 0 ? ' (' . __('best fit') . ')</b>' : ''), '</td>';
265	+					foreach ($Result['forecast'] as $Value) {
266	+						echo '<td class="number">', ForecastNumber($Value, 1), '</td>';
267	+					}
268	+					echo '<td class="number">', ForecastNumber($Result['mad'], 2), '</td>
269	+						<td class="number">', ($Result['poa'] === null ? '-' : ForecastNumber($Result['poa'], 1)), '</td>
270	+						<td class="number">', ForecastNumber($Result['mse'], 2), '</td>
271	+						<td class="number">', ForecastNumber($Result['rmse'], 2), '</td></tr>';
272	+				}
273	+				echo '</table>';
274	+			}
275	+			// methods that could not be tested are reported with the reason
276	+			$Tested = array();
277	+			foreach ($Results as $Result) {
278	+				$Tested[] = $Result['method'];
279	+			}
280	+			$Reasons = '';
281	+			foreach ($Methods as $Number => $Details) {
282	+				if (!in_array($Number, $Tested)) {
283	+					$Outcome = ForecastCompute($Number, array_slice($X, 0, count($X) - $HoldOut), $HoldOut, $P);
284	+					$Reasons .= '<tr class="striped_row"><td>' . $Number . ' - ' . $Details['name'] . '</td><td>' .
285	+						htmlspecialchars($Outcome['ok'] ? '' : $Outcome['error'], ENT_QUOTES, 'UTF-8') . '</td></tr>';
286	+				}
287	+			}
288	+			if ($Reasons != '') {
289	+				echo '<br /><table class="selection"><tr><th colspan="2">', __('Methods that could not be tested'), '</th></tr>', $Reasons, '</table>';
290	+			}
291	+		}
292	+	}
293	+}
294	+
295	+include('includes/footer.php');
