358	diff --git a/ForecastGenerate.php b/ForecastGenerate.php
359	new file mode 100644
360	index 0000000..e329bdd
361	--- /dev/null
362	+++ b/ForecastGenerate.php
363	@@ -0,0 +1,263 @@
364	+<?php
365	+
366	+// Generate forecasts for one item or for every active item of a stock category. Work is done in batches
367	+// of a few items per request, with progress shown, so that large categories do not run into time limits.
368	+
369	+require(__DIR__ . '/includes/session.php');
370	+
371	+$Title = __('Generate Forecasts');
372	+$ViewTopic = 'Forecasting';
373	+$BookMark = 'ForecastGenerate';
374	+include('includes/header.php');
375	+include('includes/ForecastFormFunctions.php');
376	+
377	+define('FORECAST_ITEMS_PER_STEP', 25);
378	+
379	+ForecastPageTitle($Title);
380	+ForecastNavigation();
381	+
382	+$Defaults = array_merge(ForecastGetParameters(), ForecastRunDefaults());
383	+$Methods = ForecastMethods();
384	+$BatchID = 0;
385	+
386	+if (isset($_POST['Generate'])) {
387	+	$InputError = 0;
388	+	$Scope = ($_POST['Scope'] == 'category') ? 'category' : 'item';
389	+	$Method = (int) $_POST['Method'];
390	+	$Horizon = (int) $_POST['Horizon'];
391	+	$LocCode = $_POST['Location'];
392	+	$P = ForecastParametersFromPost($_POST);
393	+	$Items = array();
394	+	$CategoryID = '';
395	+
396	+	if ($Horizon < 1 or $Horizon > 36) {
397	+		prnMsg(__('The horizon must be from 1 to 36 monthly periods'), 'error');
398	+		$InputError = 1;
399	+	}
400	+	if ($Method > 0) {
401	+		$Error = ForecastValidateParameters($Method, $P);
402	+		if ($Error != '') {
403	+			prnMsg($Error, 'error');
404	+			$InputError = 1;
405	+		}
406	+	} elseif ((int) $P['holdout'] != $P['holdout'] or $P['holdout'] < 1 or $P['holdout'] > 12) {
407	+		prnMsg(__('The months held out must be a whole number from 1 to 12'), 'error');
408	+		$InputError = 1;
409	+	}
410	+	if ($LocCode != '') {
411	+		$Result = DB_query("SELECT loccode FROM locationusers WHERE loccode = '" . $LocCode . "'
412	+							AND userid = '" . $_SESSION['UserID'] . "' AND canview = 1");
413	+		if (DB_num_rows($Result) == 0) {
414	+			prnMsg(__('The location is not valid or you may not use it'), 'error');
415	+			$InputError = 1;
416	+		}
417	+	}
418	+	if ($Scope == 'item') {
419	+		$StockID = trim(mb_strtoupper($_POST['StockID']));
420	+		if (ForecastItemDescription($StockID) === null) {
421	+			prnMsg(__('The item code entered is not a valid stock item'), 'error');
422	+			$InputError = 1;
423	+		} else {
424	+			$Items = array($StockID);
425	+		}
426	+	} else {
427	+		$CategoryID = $_POST['CategoryID'];
428	+		$Items = ForecastCategoryItems($CategoryID);
429	+		if (count($Items) == 0) {
430	+			prnMsg(__('The category has no active items'), 'error');
431	+			$InputError = 1;
432	+		}
433	+	}
434	+	$BestFit = ($Method == 0) ? 1 : 0;
435	+	$BatchParams = $P;
436	+	if ($InputError == 0 and $Scope == 'category' and $BestFit == 1) {
437	+		// one method for the whole category: the one that does best across its items
438	+		$Range = ForecastHistoryRange();
439	+		if ($Range['to'] === null) {
440	+			prnMsg(__('No sales history has been extracted yet'), 'error');
