+function ForecastSolve3($A, $B) {
+	// Gaussian elimination with partial pivoting for the 3x3 normal equations; null if singular
+	for ($i = 0; $i < 3; $i++) {
+		$Pivot = $i;
+		for ($r = $i + 1; $r < 3; $r++) {
+			if (abs($A[$r][$i]) > abs($A[$Pivot][$i])) {
+				$Pivot = $r;
+			}
+		}
+		if (abs($A[$Pivot][$i]) < 1e-12) {
+			return null;
+		}
+		list($A[$i], $A[$Pivot]) = array($A[$Pivot], $A[$i]);
+		list($B[$i], $B[$Pivot]) = array($B[$Pivot], $B[$i]);
+		for ($r = $i + 1; $r < 3; $r++) {
+			$Factor = $A[$r][$i] / $A[$i][$i];
+			for ($c = $i; $c < 3; $c++) {
+				$A[$r][$c] -= $Factor * $A[$i][$c];
+			}
+			$B[$r] -= $Factor * $B[$i];
+		}
+	}
+	$Solution = array(0, 0, 0);
+	for ($i = 2; $i >= 0; $i--) {
+		$Sum = $B[$i];
+		for ($c = $i + 1; $c < 3; $c++) {
+			$Sum -= $A[$i][$c] * $Solution[$c];
+		}
+		$Solution[$i] = $Sum / $A[$i][$i];
+	}
+	return $Solution;
+}
