+/* Forecast $Horizon months after the series $X (oldest first, one value per month).
+   Returns array('ok' => true, 'values' => array(...)) or array('ok' => false, 'error' => message).
+   A method that needs more history than the series holds is refused, never padded. */
+function ForecastCompute($Method, $X, $Horizon, $P) {
+	$Methods = ForecastMethods();
+	if (!isset($Methods[$Method])) {
+		return array('ok' => false, 'error' => __('The forecasting method is not valid'));
+	}
+	$Error = ForecastValidateParameters($Method, $P);
+	if ($Error != '') {
+		return array('ok' => false, 'error' => $Error);
+	}
+	$N = count($X);
+	$Min = ForecastMinHistory($Method, $P);
+	if ($N < $Min) {
+		return array('ok' => false, 'error' => sprintf(__('%s needs %d months of history but only %d are available'), $Methods[$Method]['name'], $Min, $N));
+	}
+	$F = array();
+	switch ($Method) {
+		case 1:
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $X[$N - 12 + (($h - 1) % 12)] * (1 + $P['pct'] / 100);
+			}
+			break;
+		case 2:
+			$Last = array_sum(array_slice($X, $N - 12, 12));
+			$Prior = array_sum(array_slice($X, $N - 24, 12));
+			if ($Prior <= 0) {
+				return array('ok' => false, 'error' => __('There were no sales in the year before last, so the growth cannot be calculated'));
+			}
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $X[$N - 12 + (($h - 1) % 12)] * ($Last / $Prior);
+			}
+			break;
+		case 3:
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $X[$N - 12 + (($h - 1) % 12)];
+			}
+			break;
+		case 4:
+			$Level = array_sum(array_slice($X, $N - (int) $P['maperiods'])) / (int) $P['maperiods'];
+			$F = array_fill(0, $Horizon, $Level);
+			break;
+		case 5:
+			// straight line through the latest month and the month 'pointsapart' - 1 periods earlier
+			$K = (int) $P['pointsapart'];
+			$Slope = ($X[$N - 1] - $X[$N - $K]) / ($K - 1);
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $X[$N - 1] + $Slope * $h;
+			}
+			break;
+		case 6:
+			$SumT = $SumY = $SumTT = $SumTY = 0;
+			for ($t = 1; $t <= $N; $t++) {
+				$SumT += $t;
+				$SumY += $X[$t - 1];
+				$SumTT += $t * $t;
+				$SumTY += $t * $X[$t - 1];
+			}
+			$Denominator = $N * $SumTT - $SumT * $SumT;
+			$B = ($N * $SumTY - $SumT * $SumY) / $Denominator;
+			$A = ($SumY - $B * $SumT) / $N;
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $A + $B * ($N + $h);
+			}
+			break;
+		case 7:
+			// y = a + b u + c u^2 with u centred on the middle of the history, for numerical stability
+			$Centre = ($N + 1) / 2;
+			$S = array_fill(0, 5, 0);
+			$T = array_fill(0, 3, 0);
+			for ($t = 1; $t <= $N; $t++) {
+				$u = $t - $Centre;
+				for ($k = 0; $k <= 4; $k++) {
+					$S[$k] += pow($u, $k);
+				}
+				for ($k = 0; $k <= 2; $k++) {
+					$T[$k] += pow($u, $k) * $X[$t - 1];
+				}
+			}
+			$Coefficients = ForecastSolve3(array(array($S[0], $S[1], $S[2]), array($S[1], $S[2], $S[3]), array($S[2], $S[3], $S[4])), $T);
+			if ($Coefficients === null) {
+				return array('ok' => false, 'error' => __('The second degree curve could not be fitted to this history'));
+			}
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$u = $N + $h - $Centre;
+				$F[] = $Coefficients[0] + $Coefficients[1] * $u + $Coefficients[2] * $u * $u;
+			}
+			break;
+		case 8:
+		case 9:
+			// weights apply to the most recent month first
+			$Weights = ForecastParseWeights($Method == 8 ? $P['flexweights'] : $P['wmaweights']);
+			if ($Method == 9) {
+				$Total = array_sum($Weights);
+				foreach ($Weights as $Key => $Weight) {
+					$Weights[$Key] = $Weight / $Total;
+				}
+			}
+			$Level = 0;
+			foreach ($Weights as $Key => $Weight) {
+				$Level += $Weight * $X[$N - 1 - $Key];
+			}
+			$F = array_fill(0, $Horizon, $Level);
+			break;
+		case 10:
+			$Level = $X[0];
+			for ($t = 1; $t < $N; $t++) {
+				$Level = $P['alpha'] * $X[$t] + (1 - $P['alpha']) * $Level;
+			}
+			$F = array_fill(0, $Horizon, $Level);
+			break;
+		case 11:
+			$Level = $X[0];
+			$Trend = $X[1] - $X[0];
+			for ($t = 1; $t < $N; $t++) {
+				$Previous = $Level;
+				$Level = $P['alpha'] * $X[$t] + (1 - $P['alpha']) * ($Level + $Trend);
+				$Trend = $P['beta'] * ($Level - $Previous) + (1 - $P['beta']) * $Trend;
+			}
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $Level + $h * $Trend;
+			}
+			break;
+		case 12:
+			// additive Holt-Winters, initialised from the first two seasons
+			$L = (int) $P['seasonlength'];
+			$FirstMean = array_sum(array_slice($X, 0, $L)) / $L;
+			$SecondMean = array_sum(array_slice($X, $L, $L)) / $L;
+			$Trend = ($SecondMean - $FirstMean) / $L;
+			$Level = $FirstMean + $Trend * ($L - 1) / 2;
+			$Season = array();
+			for ($i = 0; $i < $L; $i++) {
+				$Season[$i] = $X[$i] - $FirstMean - $Trend * ($i - ($L - 1) / 2);
+			}
+			for ($t = $L; $t < $N; $t++) {
+				$Previous = $Level;
+				$Level = $P['alpha'] * ($X[$t] - $Season[$t % $L]) + (1 - $P['alpha']) * ($Level + $Trend);
+				$Trend = $P['beta'] * ($Level - $Previous) + (1 - $P['beta']) * $Trend;
+				$Season[$t % $L] = $P['gamma'] * ($X[$t] - $Level) + (1 - $P['gamma']) * $Season[$t % $L];
+			}
+			for ($h = 1; $h <= $Horizon; $h++) {
+				$F[] = $Level + $h * $Trend + $Season[($N + $h - 1) % $L];
+			}
+			break;
+	}
+	foreach ($F as $Key => $Value) {
+		// a demand forecast is never negative
+		$F[$Key] = is_finite($Value) ? round(max(0, $Value), 4) : 0;
+	}
+	return array('ok' => true, 'values' => $F);
+}
