+/* MAD, MSE, RMSE and POA of forecast against actual, month for month.
+   POA (percent of accuracy) = 100 - 100 x sum|error| / sum(actual), not below 0; null when nothing was sold. */
+function ForecastMeasures($Actual, $Forecast) {
+	$N = count($Actual);
+	$SumAbs = $SumSq = $SumActual = $SumForecast = 0;
+	for ($i = 0; $i < $N; $i++) {
+		$Error = $Forecast[$i] - $Actual[$i];
+		$SumAbs += abs($Error);
+		$SumSq += $Error * $Error;
+		$SumActual += $Actual[$i];
+		$SumForecast += $Forecast[$i];
+	}
+	return array(
+		'n' => $N,
+		'mad' => $N > 0 ? $SumAbs / $N : 0,
+		'mse' => $N > 0 ? $SumSq / $N : 0,
+		'rmse' => $N > 0 ? sqrt($SumSq / $N) : 0,
+		'poa' => $SumActual > 0 ? max(0, 100 - 100 * $SumAbs / $SumActual) : null,
+		'sumabs' => $SumAbs,
+		'sumactual' => $SumActual,
+		'sumforecast' => $SumForecast
+	);
+}
