+/* Hold out the last $HoldOut months, forecast them with every method that has enough history left,
+   and rank the methods by MAD (lowest first, method number breaks ties). */
+function ForecastEvaluateMethods($X, $HoldOut, $P, $Methods = null) {
+	$N = count($X);
+	$Results = array();
+	if ($HoldOut < 1 or $HoldOut >= $N) {
+		return $Results;
+	}
+	$Train = array_slice($X, 0, $N - $HoldOut);
+	$Actual = array_slice($X, $N - $HoldOut);
+	foreach (ForecastMethods() as $Method => $Details) {
+		if ($Methods !== null and !in_array($Method, $Methods)) {
+			continue;
+		}
+		$Forecast = ForecastCompute($Method, $Train, $HoldOut, $P);
+		if ($Forecast['ok']) {
+			$Measures = ForecastMeasures($Actual, $Forecast['values']);
+			$Measures['method'] = $Method;
+			$Measures['forecast'] = $Forecast['values'];
+			$Results[] = $Measures;
+		}
+	}
+	usort($Results, function ($a, $b) {
+		if ($a['mad'] == $b['mad']) {
+			return $a['method'] - $b['method'];
+		}
+		return $a['mad'] < $b['mad'] ? -1 : 1;
+	});
+	return $Results;
+}
+
+/* Best method across several items ($SeriesList = array of series). Every method is scored by its summed
+   absolute error relative to the summed actuals over the items it could be evaluated on; only methods that
+   could be evaluated on at least half of the items that any method could be evaluated on are considered.
+   Returns array('best' => method or 0, 'stats' => array per method). */
+function ForecastEvaluateCategory($SeriesList, $HoldOut, $P) {
+	$Stats = array();
+	$ItemsEvaluated = 0;
+	foreach ($SeriesList as $X) {
+		$Results = ForecastEvaluateMethods($X, $HoldOut, $P);
+		if (count($Results) > 0) {
+			$ItemsEvaluated++;
+		}
+		foreach ($Results as $Result) {
+			if (!isset($Stats[$Result['method']])) {
+				$Stats[$Result['method']] = array('items' => 0, 'sumabs' => 0, 'sumactual' => 0, 'n' => 0);
+			}
+			$Stats[$Result['method']]['items']++;
+			$Stats[$Result['method']]['sumabs'] += $Result['sumabs'];
+			$Stats[$Result['method']]['sumactual'] += $Result['sumactual'];
+			$Stats[$Result['method']]['n'] += $Result['n'];
+		}
+	}
+	$Best = 0;
+	$BestScore = null;
+	ksort($Stats);
+	foreach ($Stats as $Method => $Stat) {
+		$Stats[$Method]['score'] = $Stat['sumactual'] > 0 ? $Stat['sumabs'] / $Stat['sumactual'] : $Stat['sumabs'];
+		$Stats[$Method]['poa'] = $Stat['sumactual'] > 0 ? max(0, 100 - 100 * $Stat['sumabs'] / $Stat['sumactual']) : null;
+		$Stats[$Method]['mad'] = $Stat['n'] > 0 ? $Stat['sumabs'] / $Stat['n'] : 0;
+		if ($Stat['items'] * 2 >= $ItemsEvaluated and ($BestScore === null or $Stats[$Method]['score'] < $BestScore)) {
+			$Best = $Method;
+			$BestScore = $Stats[$Method]['score'];
+		}
+	}
+	return array('best' => $Best, 'stats' => $Stats, 'items' => $ItemsEvaluated);
+}
